export const AXIS_KEYS = ['est', 'rep', 'pod', 'imi', 'dip', 'int', 'eco', 'con', 'com', 'rel', 'mor', 'tec'] as const;
export type AxisKey = (typeof AXIS_KEYS)[number];
export type ReferenceKind = 'ideology' | 'person' | 'country';
export type ReferenceCategory = 'ideology' | 'public-figure' | 'historical-figure' | 'country' | 'historical-country';
export interface ReferenceSource { title: string; url: string; note: string }
export interface ReferenceEntry {
  id: string;
  kind: ReferenceKind;
  /** Editorial grouping independent of matching kind, which remains stable for compatibility. */
  category: ReferenceCategory;
  name: string;
  /** Alternate names for the same person, country-government, or doctrine. */
  aliases?: string[];
  period: string;
  vec: Record<AxisKey, number>;
  rationale: string;
  caveats: string;
  sources: ReferenceSource[];
  /** Evidence strength for each axis; absent keys mean unknown and require a centered score. */
  evidence: Partial<Record<AxisKey, 'high' | 'medium' | 'low'>>;
  /** New profiles cite the specific source(s) and reasoning behind every non-center axis. */
  axisEvidence?: Partial<Record<AxisKey, { sourceTitles: string[]; rationale: string }>>;
  /** Versioned editorial claims and anchors; metadata alone does not certify documentary review. */
  coding?: Partial<Record<AxisKey, AuditableAxisCoding>>;
}

// Axis order: federalism, democracy, security, assimilation, militarism,
// non-intervention, public ownership, planning, protectionism, secularism,
// progressivism, technological optimism. 100 is always the first pole.
const vector = (v: [number, number, number, number, number, number, number, number, number, number, number, number]): Record<AxisKey, number> =>
  Object.fromEntries(AXIS_KEYS.map((key, i) => [key, v[i]])) as Record<AxisKey, number>;
const source = (title: string, url: string, note: string): ReferenceSource => ({ title, url, note });

